namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;

    // Simulates an initial batch that would come from a database.
    public List<Notification> GetInitialNotifications() =>
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
        new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-1)),
    ];

    // Simulates a poll that occasionally returns a new notification.
    public Notification? CheckForNew()
    {
        // ~30% chance of a new notification per poll
        if (Random.Shared.Next(0, 10) < 3)
        {
            var id = Interlocked.Increment(ref _nextId);
            return new Notification(id, $"New event #{id} occurred.", DateTime.UtcNow);
        }

        return null;
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both prerender and interactive render.
    // Loads initial data so it appears in the server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetInitialNotifications();
    }

    // Only called once the component is fully interactive (not during prerender).
    // This is where we start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newNotification = NotificationService.CheckForNew();
            if (newNotification is not null)
            {
                _notifications.Add(newNotification);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

